content.css:
#cortex-chat-root {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
  font-family: "Segoe UI", sans-serif;
  background: white;
  border: 1px solid #d9d9d9;
  border-radius: 8px;
}
.chat-header {
  background: #0078d4;
  color: white;
  font-size: 16px;
  font-weight: 600;
  padding: 12px;
}
.chat-body {
  flex: 1;
  padding: 16px;
  overflow-y: auto;
  font-size: 14px;
}
.chat-footer {
  display: flex;
  gap: 10px;
  padding: 12px;
  border-top: 1px solid #d9d9d9;
}
.chat-footer input {
  flex: 1;
  padding: 8px 12px;
  font-size: 14px;
}
.chat-footer button {
  padding: 8px 18px;
  background: #0078d4;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}
.chat-footer button:hover {
  background: #106ebe;
}

#cortex-chat {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
  background: white;
  font-family: Segoe UI, sans-serif;
}
.chat-header {
  background: #0078D4;
  color: white;
  padding: 15px;
}
.title {
  font-size: 18px;
  font-weight: 600;
}
.subtitle {
  font-size: 12px;
  margin-top: 4px;
  opacity: 0.9;
}
#messages {
  flex: 1;
  overflow: auto;
  padding: 15px;
  background: #F8F8F8;
}
.assistant-message {
  background: white;
  padding: 12px;
  border-radius: 10px;
  width: fit-content;
  max-width: 80%;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
}
.chat-footer {
  display: flex;
  padding: 12px;
  gap: 10px;
  border-top: 1px solid #ddd;
}
.chat-footer input {
  flex: 1;
  padding: 10px;
  font-size: 14px;
}
.chat-footer button {
  background: #0078D4;
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 6px;
  cursor: pointer;
}
.user-message {
  margin-top: 15px;
  background: #0078D4;
  color: white;
  padding: 12px;
  border-radius: 10px;
  margin-left: auto;
  width: fit-content;
  max-width: 80%;
}
